/* ---------------- 工具 ---------------- */
const $ = s => document.querySelector(s);
const $$ = s => Array.from(document.querySelectorAll(s));
function rnd(a,b){ return Math.floor(Math.random()*(b-a+1))+a; }
function shuffle(a){ a=a.slice(); for(let i=a.length-1;i>0;i--){ const j=rnd(0,i); [a[i],a[j]]=[a[j],a[i]]; } return a; }
function sample(arr,k){ return shuffle(arr).slice(0,k); }

/* ---------------- 学习状态 ---------------- */
function defaultState(){ return { name:'', stars:0, level:1, badges:{}, customPoems:[], libPoems:[], builtinOrder:null, hiddenBuiltin:{}, stats:{letter:0,poem:0,math:0,logic:0,adventure:0,pinyin:0,shape:0,char:0}, screenMin:15, parentPwd:'', usedDate:'', usedSec:0 }; }
let state;
try{ state = JSON.parse(window.__learningState) || defaultState(); }catch(e){ state = defaultState(); }
if(!state.stats) state.stats = defaultState().stats;
if(!state.badges) state.badges = {};
if(!state.customPoems) state.customPoems = [];
function save(){ window.__saveLearningState(JSON.stringify(state)); }

/* ---------------- 发音（离线音频优先：微软神经嗓音预生成 mp3；不支持音频的浏览器回退 Web Speech） ---------------- */
function pickVoice(lang){
  const vs = (window.speechSynthesis && window.speechSynthesis.getVoices()) || [];
  if(!vs.length) return null;
  const base = (lang||'zh-CN').toLowerCase();
  const match = vs.filter(v=> v.lang && v.lang.toLowerCase().indexOf(base)===0);
  if(!match.length) return null;
  // 优先挑“神经/在线/大厂”嗓音，机器味更轻
  const pref = base.indexOf('en')===0
    ? ['Google US English','Microsoft','Samantha','Natural','English']
    : ['Neural','Online','Microsoft','Google','Yue','Ting','Huihui','Chinese'];
  for(const p of pref){
    const f = match.find(v=> v.name && v.name.toLowerCase().indexOf(p.toLowerCase())>=0);
    if(f) return f;
  }
  return match[0];
}

let _audioEl = null;
function playAsset(file, fallbackText, lang){
  void window.__playLearningAudio(file).catch(() => speakWeb(fallbackText, lang));
}
function speak(text, lang){
  lang = lang || 'zh-CN';
  // 固定内容优先用预生成音频（兼容 Via 等无语音引擎的浏览器）
  if(lang === 'en-US' && text.length === 1 && /[A-Z]/.test(text)){
    return playAsset('letter_' + text + '.mp3', text, lang);
  }
  if(lang === 'zh-CN' && /^\d+$/.test(text) && (+text) <= 20){
    return playAsset('num_' + text + '.mp3', text, lang);
  }
  return speakWeb(text, lang);
}
function playFullOrBody(fullFile, bodyFile, text){
  void window.__playLearningAudio(fullFile).catch(() => playAsset(bodyFile, text, 'zh-CN'));
}
function playPoem(idx, text){ playFullOrBody('poem_full_' + idx + '.mp3', 'poem_' + idx + '.mp3', text); }
function speakWeb(text, lang){
  lang = lang || 'zh-CN';
  try{
    if(!('speechSynthesis' in window)){
      toast('这个窗口不支持发音，请用手机或电脑上的 Chrome / Edge / Safari 打开链接');
      return;
    }
    const ss = window.speechSynthesis;
    ss.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = lang; u.rate = 0.9; u.pitch = 1.1;
    const v = pickVoice(lang);
    if(v) u.voice = v;
    // 部分引擎在 cancel 后需要极短延迟才稳定出声
    setTimeout(()=>{ try{ ss.speak(u); }catch(e){} }, 60);
  }catch(e){
    toast('发音出错了，换个浏览器试试');
  }
}
// 预热嗓音列表（部分浏览器异步加载）
if('speechSynthesis' in window){
  window.speechSynthesis.getVoices();
  window.speechSynthesis.onvoiceschanged = ()=> window.speechSynthesis.getVoices();
}

