/* ---------------- SVG ---------------- */
function starSVG(s){ s=s||24; return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 24 24"><path d="M12 2l2.9 6.1 6.6.9-4.8 4.6 1.2 6.6L12 17.8 6.1 20.2l1.2-6.6L2.5 9l6.6-.9z" fill="#FFC83D" stroke="#FFB300" stroke-width="0.6"/></svg>'; }
function colorFor(t){ return ({circle:'#7EC8F3',square:'#FF8FB8',triangle:'#8FDDA0',star:'#FFD56B',heart:'#C4A3F5'})[t]||'#FF8FB8'; }
function shapeSVG(t,s,c){ s=s||60; c=c||colorFor(t);
  if(t==='circle') return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 60 60"><circle cx="30" cy="30" r="24" fill="'+c+'"/></svg>';
  if(t==='square') return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 60 60"><rect x="8" y="8" width="44" height="44" rx="10" fill="'+c+'"/></svg>';
  if(t==='triangle') return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 60 60"><polygon points="30,6 54,52 6,52" fill="'+c+'"/></svg>';
  if(t==='star') return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 60 60"><path d="M30 6l6.5 14 15 2-11 10.5 2.7 15L30 41l-13.2 7 2.7-15L8.5 22l15-2z" fill="'+c+'"/></svg>';
  if(t==='heart') return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 60 60"><path d="M30 50 C10 34 6 22 16 14 C24 8 30 16 30 20 C30 16 36 8 44 14 C54 22 50 34 30 50 Z" fill="'+c+'"/></svg>';
  return '';
}
// 带属性（形状/颜色/大小/旋转）的图形，用于逻辑匹配题：示例与正确答案完全一致，干扰项只改一个属性
function baseShapeInner(sh){
  if(sh==='circle') return '<circle cx="30" cy="30" r="22" fill="FILL"/>';
  if(sh==='square') return '<rect x="11" y="11" width="38" height="38" rx="9" fill="FILL"/>';
  if(sh==='triangle') return '<polygon points="30,7 53,51 7,51" fill="FILL"/>';
  if(sh==='star') return '<path d="M30 6l6.5 14 15 2-11 10.5 2.7 15L30 41l-13.2 7 2.7-15L8.5 22l15-2z" fill="FILL"/>';
  if(sh==='heart') return '<path d="M30 50 C10 34 6 22 16 14 C24 8 30 16 30 20 C30 16 36 8 44 14 C54 22 50 34 30 50 Z" fill="FILL"/>';
  return '';
}
function figSVG(fig, s){
  s=s||60;
  const col=fig.c||'#7EC8F3'; const k=fig.sz||1; const rot=fig.rot||0;
  const inner=baseShapeInner(fig.sh).replace(/FILL/g, col);
  return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 60 60"><g transform="translate(30,30) scale('+k+') rotate('+rot+') translate(-30,-30)">'+inner+'</g></svg>';
}
function speakerSVG(){ return '<svg viewBox="0 0 24 24"><path d="M4 9v6h4l5 5V4L8 9z" fill="#fff"/><path d="M16 8a5 5 0 0 1 0 8" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round"/></svg>'; }
function shape3dSVG(t,s){ s=s||70;
  if(t==='cube') return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 60 60"><polygon points="30,9 47,18 47,42 30,51 13,42 13,18" fill="#7EC8F3"/><polygon points="30,9 47,18 30,26 13,18" fill="#BDE6FB"/><polygon points="13,18 30,26 30,51 13,42" fill="#6FBEEA"/><polygon points="47,18 30,26 30,51 47,42" fill="#5BB0E8"/></svg>';
  if(t==='cuboid') return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 60 60"><polygon points="9,25 49,25 57,17 17,17" fill="#BDE6FB"/><polygon points="49,25 57,17 57,37 49,45" fill="#5BB0E8"/><polygon points="9,25 49,25 49,45 9,45" fill="#6FBEEA"/></svg>';
  if(t==='sphere') return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 60 60"><circle cx="30" cy="30" r="22" fill="#FF8FB8"/><ellipse cx="23" cy="23" rx="7" ry="5" fill="#FFD0E2" opacity="0.8"/></svg>';
  if(t==='cylinder') return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 60 60"><rect x="16" y="16" width="28" height="28" fill="#C4A3F5"/><ellipse cx="30" cy="44" rx="14" ry="6" fill="#A987E0"/><ellipse cx="30" cy="16" rx="14" ry="6" fill="#E0CEF8" stroke="#A987E0" stroke-width="1"/></svg>';
  if(t==='cone') return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 60 60"><polygon points="30,10 46,44 14,44" fill="#8FDDA0"/><ellipse cx="30" cy="44" rx="16" ry="6" fill="#6FCB82"/></svg>';
  if(t==='prism') return '<svg width="'+s+'" height="'+s+'" viewBox="0 0 60 60"><polygon points="13,49 28,42 47,49" fill="#7CAB55"/><polygon points="13,18 28,11 28,42 13,49" fill="#C8E6A0"/><polygon points="13,18 28,11 47,18" fill="#E0F0BC"/><polygon points="28,11 47,18 47,49 28,42" fill="#9CCB66"/></svg>';
  return '';
}

