/* ---------------- 星星 / 徽章 ---------------- */
function addStar(n){ n=n||1; state.stars+=n; state.level=Math.floor(state.stars/10)+1; save(); checkBadges(); refresh(); }
function unlock(id){ if(state.badges[id]) return; state.badges[id]=true; save(); const b=BADGES.find(x=>x.id===id); toast('解锁徽章：'+(b?b.name:id)+'！', true); }
function checkBadges(){
  if(state.stars>=1) unlock('b_first');
  if(state.stats.letter>=5) unlock('b_letter');
  if(state.stats.poem>=3) unlock('b_poem');
  if(state.stats.math>=10) unlock('b_math');
  if(state.stats.logic>=5) unlock('b_logic');
  if(state.level>=3) unlock('b_level3');
  if(state.stars>=30) unlock('b_star30');
  if(state.stats.adventure>=5) unlock('b_allround');
  if(state.stats.pinyin>=5) unlock('b_pinyin');
  if(state.stats.shape>=5) unlock('b_shape');
  if(state.stats.char>=5) unlock('b_char');
}

/* ---------------- Toast ---------------- */
let toastTimer;
function toast(msg, big){
  const t=$('#toast'); t.textContent=msg;
  if(big){ const icon=document.createElement('span'); icon.className='tstar'; icon.innerHTML=starSVG(22); t.prepend(icon); }
  t.className='toast show'+(big?' big':'');
  clearTimeout(toastTimer); toastTimer=setTimeout(()=>t.className='toast', big?2400:1500);
}

/* ---------------- 刷新界面 ---------------- */
function refresh(){
  $('#star-count-top').textContent=state.stars;
  $('#level-badge').textContent='Lv.'+state.level;
  $('#home-stars').textContent=state.stars;
  $('#home-level').textContent=state.level;
  const earned=Object.keys(state.badges).length;
  $('#home-badges').textContent=earned+' / '+BADGES.length;
  renderBadges($('#badge-wall'));
  renderBadges($('#badge-wall-adv'));
}
function renderBadges(wrap){
  if(!wrap) return; wrap.innerHTML='';
  BADGES.forEach(b=>{
    const got=!!state.badges[b.id];
    const d=document.createElement('div'); d.className='badge'+(got?' got':'');
    d.innerHTML='<div class="badge-ico">'+starSVG(46)+'</div><div class="badge-name">'+b.name+'</div><div class="badge-desc">'+b.desc+'</div>';
    wrap.appendChild(d);
  });
}

/* ---------------- 名字：XX 专属学习乐园 ---------------- */
function kidName(){ return (state.name && state.name.trim()) ? state.name.trim() : '小朋友'; }
function appTitle(){ return kidName() + '专属学习乐园'; }
function applyName(){
  const t=appTitle();
  try{ document.title=t; }catch(e){}
  const bn=$('#brand-name'); if(bn) bn.textContent=t;
  const hi=$('#hero-hi'); if(hi) hi.textContent='嗨，'+kidName()+'！今天想玩什么呀？';
  const pt=$('#page-title');
  if(pt && (pt.textContent==='宝贝学习乐园' || pt.textContent.indexOf('专属学习乐园')>=0)) pt.textContent=t;
}
function askName(){
  const mask=$('#name-modal'); if(!mask) return;
  const inp=$('#name-input'); const ok=$('#name-ok');
  if(!inp||!ok) return;
  inp.value=state.name||'';
  mask.classList.remove('hide');
  setTimeout(()=>{ try{ inp.focus(); }catch(e){} }, 150);
  const submit=()=>{
    const v=(inp.value||'').trim();
    if(!v){ toast('请先写上名字哦～'); return; }
    state.name=v.slice(0,8); save(); applyName();
    mask.classList.add('hide');
    toast('欢迎你，'+state.name+'！', true);
  };
  ok.onclick=submit;
  inp.onkeydown=e=>{ if(e.key==='Enter') submit(); };
}

