/* ---------------- 护眼计时 / 家长解锁 ---------------- */
const DEFAULT_PARENT_PWD='8888';
let _restLocked=false, _restTimer=null, _saveTick=0;
function _todayStr(){ const d=new Date(); return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate(); }
function _limitSec(){ return (state.screenMin||15)*60; }
function _fmt(sec){ sec=Math.max(0,Math.floor(sec)); const m=Math.floor(sec/60), s=sec%60; return (m<10?'0':'')+m+':'+(s<10?'0':'')+s; }
function updateTimerPill(){
  const el=$('#play-timer'); if(!el) return;
  const left=_limitSec()-(state.usedSec||0);
  if(_restLocked){ el.textContent='该休息啦'; el.className='timer-pill rest'; return; }
  el.textContent='还能玩 '+_fmt(left);
  el.className='timer-pill'+(left<=60?' warn':'');
}
function newMathQ(){
  const a=2+Math.floor(Math.random()*8), b=2+Math.floor(Math.random()*8);
  const q=$('#rest-math-q'); if(q) q.textContent=a+' × '+b+' = ?';
  const ans=$('#rest-math-ans'); if(ans){ ans.value=''; ans.dataset.ans=a*b; }
}
function openRest(){
  if(_restLocked) return;
  _restLocked=true;
  const err=$('#rest-err'); if(err) err.textContent='';
  $$('#rest-modal .ut').forEach(t=>t.classList.toggle('on', t.dataset.tab==='pwd'));
  const up=$('#ut-pwd'); if(up) up.classList.remove('hide');
  const um=$('#ut-math'); if(um) um.classList.add('hide');
  const rp=$('#rest-pwd'); if(rp) rp.value='';
  newMathQ();
  const m=$('#rest-modal'); if(m) m.classList.remove('hide');
  updateTimerPill();
}
function closeRest(){
  _restLocked=false;
  const m=$('#rest-modal'); if(m) m.classList.add('hide');
  const t=_todayStr();
  if(state.usedDate!==t){ state.usedDate=t; state.usedSec=0; }
  state.usedSec=0; save();
  updateTimerPill();
}
function doUnlock(kind){
  const err=$('#rest-err'); if(!err) return;
  if(kind==='pwd'){
    const v=$('#rest-pwd').value.trim();
    if(!v){ err.textContent='请输入家长密码'; return; }
    if(v!==(state.parentPwd||DEFAULT_PARENT_PWD)){ err.textContent='密码不对，再试试～'; const rp=$('#rest-pwd'); if(rp) rp.value=''; return; }
  }else{
    const ansEl=$('#rest-math-ans'); if(!ansEl){ return; }
    const v=parseInt(ansEl.value,10);
    if(isNaN(v)){ err.textContent='请写出答案'; return; }
    if(v!==parseInt(ansEl.dataset.ans,10)){ err.textContent='算错啦，再算一次～'; newMathQ(); return; }
  }
  closeRest();
  toast('解锁成功，继续玩吧！记得爱护眼睛～', true);
}
function startScreenTimer(){
  const t=_todayStr();
  if(state.usedDate!==t){ state.usedDate=t; state.usedSec=0; save(); }
  updateTimerPill();
  if(_restTimer) return;
  _restTimer=setInterval(()=>{
    if(_restLocked) return;
    if(document.visibilityState!=='visible') return;
    state.usedSec=(state.usedSec||0)+1;
    _saveTick++; if(_saveTick>=10){ save(); _saveTick=0; }
    if(state.usedSec>=_limitSec()){ openRest(); return; }
    updateTimerPill();
  },1000);
}
function openParentSet(){
  const m=$('#parent-modal'); if(!m) return;
  const pm=$('#pm-min'); if(pm) pm.value=String(state.screenMin||15);
  const pp=$('#pm-pwd'); if(pp) pp.value=state.parentPwd||'';
  m.classList.remove('hide');
  setTimeout(()=>{ const x=$('#pm-min'); if(x) try{ x.focus(); }catch(e){} },150);
}
function initScreen(){
  $$('#rest-modal .ut').forEach(t=> t.onclick=()=>{
    $$('#rest-modal .ut').forEach(x=>x.classList.toggle('on', x===t));
    const up=$('#ut-pwd'); if(up) up.classList.toggle('hide', t.dataset.tab!=='pwd');
    const um=$('#ut-math'); if(um) um.classList.toggle('hide', t.dataset.tab!=='math');
    if(t.dataset.tab==='math') newMathQ();
    const err=$('#rest-err'); if(err) err.textContent='';
  });
  const rp=$('#rest-pwd-ok'); if(rp) rp.onclick=()=>doUnlock('pwd');
  const ri=$('#rest-pwd'); if(ri) ri.onkeydown=e=>{ if(e.key==='Enter') doUnlock('pwd'); };
  const mo=$('#rest-math-ok'); if(mo) mo.onclick=()=>doUnlock('math');
  const mi=$('#rest-math-ans'); if(mi) mi.onkeydown=e=>{ if(e.key==='Enter') doUnlock('math'); };
  const ps=$('#parent-set-btn'); if(ps) ps.onclick=openParentSet;
  const po=$('#pm-ok'); if(po) po.onclick=()=>{
    const pm=$('#pm-min'); const min=pm?parseInt(pm.value,10):15;
    state.screenMin=(min>=1&&min<=120)?min:15;
    const pp=$('#pm-pwd'); state.parentPwd=pp?((pp.value||'').trim().slice(0,12)):'';
    save();
    const m=$('#parent-modal'); if(m) m.classList.add('hide');
    updateTimerPill();
    toast('已保存：每次可玩 '+state.screenMin+' 分钟'+(state.parentPwd?'，密码已设置':''), true);
  };
  startScreenTimer();
}
if(document.readyState==='loading') window.addEventListener('DOMContentLoaded', initScreen);
else initScreen();

/* ---------------- 通用出题渲染 ---------------- */
function renderQ(wrap, q, onOk, onNo){
  const playBtn = q.qaudio ? '<div style="text-align:center;margin:8px 0"><button class="mini-btn q-play">'+speakerSVG()+' 播放</button></div>' : '';
  wrap.innerHTML='<div class="q-prompt">'+q.prompt+playBtn+'</div><div class="q-opts"></div>';
  const ow=wrap.querySelector('.q-opts');
  let missed=false, done=false;   // 本题是否已答错过 / 是否已答完（答对后锁定，防重复加星）
  q.options.forEach(o=>{
    const b=document.createElement('button'); b.className='opt-btn';
    b.innerHTML = (o.html!==undefined)?o.html:'<span>'+o.t+'</span>';
    b.onclick=()=>{
      if(done) return;
      if(o.c){ done=true; b.classList.add('ok'); onOk&&onOk(missed); }
      else { missed=true; b.classList.add('no'); onNo&&onNo(q.tip); }
    };
    ow.appendChild(b);
  });
  if(q.qaudio){ const pb=wrap.querySelector('.q-play'); if(pb) pb.onclick=()=>playAsset(q.qaudio); }
}
function runGame(areaId, gen, extraStat){
  const wrap=$('#'+areaId);
  const q=gen();
  renderQ(wrap, q, (missed)=>{
    state.stats[q.stat]=(state.stats[q.stat]||0)+1;
    if(extraStat) state.stats[extraStat]=(state.stats[extraStat]||0)+1;
    save(); checkBadges();
    if(missed){
      playCorrect(); toast('答对啦！不过刚才错过一次，这题就不加星咯～');
    }else{
      addStar(1); playCorrect(); toast('太棒了！+1 颗星');
    }
    setTimeout(()=>runGame(areaId,gen,extraStat), 850);
  }, (tip)=>{ playWrong(); toast(tip? '💡 '+tip : '再试试看～'); });
}

/* ---------------- 出题生成器 ---------------- */
function genLetterQ(){
  const i=rnd(0,25); const up=String.fromCharCode(65+i); const low=up.toLowerCase();
  // 50% 大找小，50% 小找大
  if(Math.random()<0.5){
    const others=sample('abcdefghijklmnopqrstuvwxyz'.split('').filter(x=>x!==low),3);
    return { prompt:'请把 <b>'+up+'</b> 的<b>小写</b>字母找出来', stat:'letter',
      options:shuffle([{t:low,c:true},...others.map(x=>({t:x,c:false}))]) };
  } else {
    const others=sample('ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').filter(x=>x!==up),3);
    return { prompt:'请把 <b>'+low+'</b> 的<b>大写</b>字母找出来', stat:'letter',
      options:shuffle([{t:up,c:true},...others.map(x=>({t:x,c:false}))]) };
  }
}
function genMathQ(){
  const add=Math.random()<0.5; let a,b,ans;
  if(add){ a=rnd(1,9); b=rnd(1,10-a); ans=a+b; }
  else { a=rnd(2,10); b=rnd(1,a); ans=a-b; }
  const pool=shuffle([ans+1,ans-1,ans+2,ans-2,ans+3,ans+4].filter(x=>x>=0&&x!==ans)).slice(0,3);
  return { prompt:'算一算：<b>'+a+' '+(add?'+':'−')+' '+b+' = ?</b>', stat:'math',
    options:shuffle([{t:ans,c:true},...pool.map(x=>({t:x,c:false}))]) };
}
function genCountQ(){
  const n=rnd(1,10); let s=''; for(let i=0;i<n;i++) s+=starSVG(30);
  const pool=shuffle([n+1,n-1,n+2,n+3,n-2].filter(x=>x>=1&&x<=12&&x!==n)).slice(0,3);
  return { prompt:'数一数有几颗星星？<div class="count-shapes">'+s+'</div>', stat:'math',
    options:shuffle([{t:n,c:true,html:'<b>'+n+'</b>'},...pool.map(x=>({t:x,c:false,html:'<b>'+x+'</b>'}))]) };
}
// 真实物品 emoji 分组（5岁孩子熟悉）
