/* ===== 逻辑挑战：题型参考「大班逻辑思维能力练习卷」7 大类，全部可无限随机生成 ===== */
const GROUP_CN={fruit:'水果',animal:'动物',bird:'小鸟',food:'食物',vehicle:'交通工具',flower:'花草',nature:'自然现象',ball:'球类'};
