/* 选项：图 + 文字 的通用包装 */
function optHTML(svg,label){ return '<div style="display:flex;flex-direction:column;align-items:center;gap:4px">'+svg+'<span>'+label+'</span></div>'; }
function numOpt(n){ return '<b style="font-size:22px">'+n+'</b>'; }

/* ================= 图形题型生成器（对应大班图形卷四大类，全部配图） ================= */
