SHAPE_GENS.push(function gPickSolidKind(){       // 大纲 5、6：认立体图形
  var i=rnd(0,SHAPES.length-1), qs=SHAPES[i];
  var id=qs.f.replace('shape_','').replace('.mp3','');
  var others=sample(SHAPES.filter(function(s){ return s.f!==qs.f; }),3);
  var opts=shuffle([{t:qs.name,c:true}].concat(others.map(function(s){ return {t:s.name,c:false}; })));
  return { prompt:'这是什么立体图形？<div class="ex-shape">'+solidSVG(id,90)+'</div>', stat:'shape', options:opts,
    tip:'看它的样子：方方的是正方体/长方体，圆圆能滚的是球体，上下两个圆的是圆柱体。' };
});

/* ---- 二、图形特征 ---- */
SHAPE_GENS.push(function gCountSides(){          // 大纲 7、8：数边
  var m={triangle:3,square:4,rect:4,pentagon:5,hexagon:6};
  var k=pick(['triangle','square','rect','pentagon','hexagon']), n=m[k];
  var pool=shuffle([n+1,n-1,n+2,n-2].filter(function(x){ return x>=2&&x<=8&&x!==n; })).slice(0,3);
  return { prompt:'数一数，这个图形有<b>几条边</b>？<div class="ex-shape">'+flatSVG(k,90)+'</div>', stat:'shape',
    options:shuffle([{t:n,c:true,html:numOpt(n)}].concat(pool.map(function(x){ return {t:x,c:false,html:numOpt(x)}; }))),
    tip:'沿着边一条一条数，数完一圈就是边数。' };
});
SHAPE_GENS.push(function gCountCorners(){        // 大纲 7、8：数角
  var m={triangle:3,square:4,rect:4,pentagon:5,hexagon:6};
  var k=pick(['triangle','square','rect','pentagon','hexagon']), n=m[k];
  var pool=shuffle([n+1,n-1,n+2,n-2].filter(function(x){ return x>=2&&x<=8&&x!==n; })).slice(0,3);
  return { prompt:'数一数，这个图形有<b>几个角</b>？<div class="ex-shape">'+flatSVG(k,90)+'</div>', stat:'shape',
    options:shuffle([{t:n,c:true,html:numOpt(n)}].concat(pool.map(function(x){ return {t:x,c:false,html:numOpt(x)}; }))),
    tip:'尖尖的地方就是角，有几个尖就有几个角。' };
});
SHAPE_GENS.push(function gCircleCorner(){        // 大纲 10：圆形有角吗
  return { prompt:'圆形有几个角？<div class="ex-shape">'+flatSVG('circle',90)+'</div>', stat:'shape',
    options:shuffle([{t:'0',c:true,html:'<b style="font-size:22px">0 个</b>'},
      {t:'1',c:false,html:'<b style="font-size:22px">1 个</b>'},
      {t:'3',c:false,html:'<b style="font-size:22px">3 个</b>'},
      {t:'4',c:false,html:'<b style="font-size:22px">4 个</b>'}]),
    tip:'圆形一个角都没有，它的边是弯弯的曲线。' };
});
SHAPE_GENS.push(function gCubeFaces(){           // 大纲 11：正方体几个面
  return { prompt:'正方体有几个面？<div class="ex-shape">'+solidSVG('cube',90)+'</div>', stat:'shape',
    options:shuffle([{t:'6',c:true,html:'<b style="font-size:22px">6 个</b>'},
      {t:'4',c:false,html:'<b style="font-size:22px">4 个</b>'},
      {t:'5',c:false,html:'<b style="font-size:22px">5 个</b>'},
      {t:'8',c:false,html:'<b style="font-size:22px">8 个</b>'}]),
    tip:'正方体有 6 个面，每个面都是正方形：上下、左右、前后。' };
});
SHAPE_GENS.push(function gCylinderFace(){        // 大纲 12：圆柱上下是什么形状
  return { prompt:'圆柱体的上面和下面是什么形状？<div class="ex-shape">'+solidSVG('cylinder',90)+'</div>', stat:'shape',
    options:shuffle([{t:'圆形',c:true},{t:'正方形',c:false},{t:'三角形',c:false},{t:'长方形',c:false}]),
    tip:'圆柱的上下两个面都是圆圆的，中间是弯弯的面。' };
});

/* ---- 三、图形组合与分割 ---- */
SHAPE_GENS.push(function gTwoTriangles(){        // 大纲 13
  var t=pick(['square','triangle','para']);
  var nm={square:'正方形',triangle:'大三角形',para:'平行四边形'}[t];
  return { prompt:'两个一样大的三角形拼在一起，变成了什么图形？<div class="ex-shape">'+svgTwoTri(t)+'</div>', stat:'shape',
    options:shuffle([{t:nm,c:true}].concat(sample(['正方形','大三角形','平行四边形','长方形'].filter(function(x){ return x!==nm; }),3).map(function(x){ return {t:x,c:false}; }))),
    tip:'看虚线两边：是两个一样的三角形拼起来的。' };
});
SHAPE_GENS.push(function gFoldSquare(){          // 大纲 14
  var dir=pick(['v','d']);
  var ans = dir==='d' ? '两个三角形' : '两个长方形';
  return { prompt:'把正方形沿着虚线对折，分成两个一样的什么图形？<div class="ex-shape">'+svgFoldSquare(dir)+'</div>', stat:'shape',
    options:shuffle([{t:ans,c:true}].concat(sample(['两个长方形','两个三角形','两个正方形','两个圆'].filter(function(x){ return x!==ans; }),3).map(function(x){ return {t:x,c:false}; }))),
    tip:'沿着虚线折一折，看看折出来是什么样子。' };
});
SHAPE_GENS.push(function gFourSquares(){         // 大纲 15
  return { prompt:'4 个一样大的小正方形，拼成了什么大图形？<div class="ex-shape">'+svgFourSquares()+'</div>', stat:'shape',
    options:shuffle([{t:'大正方形',c:true},{t:'长方形',c:false},{t:'三角形',c:false},{t:'圆形',c:false}]),
    tip:'2 个一行、2 个一列，横竖都是 2 个，拼起来还是正方形。' };
});
SHAPE_GENS.push(function gCutRect(){             // 大纲 16
  var mode=pick(['v','d','t']);
  var ans = mode==='v' ? '两个长方形' : (mode==='d' ? '两个三角形' : '两个梯形');
  return { prompt:'长方形沿着虚线剪一刀，分成两个什么图形？<div class="ex-shape">'+svgCutRect(mode)+'</div>', stat:'shape',
    options:shuffle([{t:ans,c:true}].concat(sample(['两个长方形','两个三角形','两个梯形','两个正方形'].filter(function(x){ return x!==ans; }),3).map(function(x){ return {t:x,c:false}; }))),
    tip:'沿着虚线剪开，看看两边各是什么形状。' };
});
SHAPE_GENS.push(function gTriSplit(){            // 大纲 18
  var n=rnd(2,4);
  var pool=shuffle([n+1,n-1,n+2].filter(function(x){ return x>=1&&x<=6&&x!==n; })).slice(0,3);
  return { prompt:'这个大三角形被分成了几个小三角形？<div class="ex-shape">'+svgTriSplit(n)+'</div>', stat:'shape',
    options:shuffle([{t:n,c:true,html:numOpt(n)}].concat(pool.map(function(x){ return {t:x,c:false,html:numOpt(x)}; }))),
    tip:'数一数里面有几个小三角形，别漏了。' };
});

/* ---- 四、空间与推理 ---- */
SHAPE_GENS.push(function gBallVsCircle(){        // 大纲 19：球 vs 圆（平面立体易错）
  var solid=pick(['sphere','cube']);
  var opts=shuffle([{html:optHTML(solidSVG(solid,66),'①'),c:true},
    {html:optHTML(flatSVG('circle',66),'②'),c:false},
    {html:optHTML(flatSVG('square',66),'③'),c:false},
    {html:optHTML(flatSVG('triangle',66),'④'),c:false}]);
  return { prompt:'哪个<b>能拿在手里滚一滚</b>？', stat:'shape', options:opts,
    tip:'立体图形能拿在手里，圆只能画在纸上——平面的只能看，立体的能拿。' };
});
SHAPE_GENS.push(function gRotatedSquare(){       // 大纲 20：旋转后还是正方形吗
  return { prompt:'正方形转一下变成这样，它还是正方形吗？<div class="ex-shape">'+flatSVG('square',90,45)+'</div>', stat:'shape',
    options:shuffle([{t:'还是正方形',c:true},{t:'不是，是菱形',c:false},{t:'不是，是三角形',c:false},{t:'不是，是长方形',c:false}]),
    tip:'转一转只是方向变了，4 条边还是一样长、4 个角还是一样大，所以它还是正方形。' };
});
SHAPE_GENS.push(function gFoldCircle(){          // 大纲 24
  var folds=pick([1,2]);
  var ans=folds===1?2:4;
  return { prompt:'圆形纸对折'+(folds===1?'一':'再')+'次，打开后分成几份？<div class="ex-shape">'+svgFoldCircle(folds)+'</div>', stat:'shape',
    options:shuffle([{t:ans,c:true,html:'<b style="font-size:22px">'+ans+' 份</b>'}].concat(
      shuffle([2,3,4,6,8].filter(function(x){ return x!==ans; })).slice(0,3).map(function(x){ return {t:x,c:false,html:'<b style="font-size:22px">'+x+' 份</b>'}; }))),
    tip:'对折 1 次分成 2 份，再对折一次就分成 4 份。' };
});
SHAPE_GENS.push(function gCountBlocks(){         // 大纲 23：数方块
  var bottom=rnd(3,5), top=rnd(1,2), total=bottom+top;
  var pool=shuffle([total+1,total-1,total+2,total-2].filter(function(x){ return x>=2&&x<=9&&x!==total; })).slice(0,3);
  return { prompt:'数一数，一共有几个小正方体？<div class="ex-shape">'+svgBlocks(bottom,top)+'</div>', stat:'shape',
    options:shuffle([{t:total,c:true,html:numOpt(total)}].concat(pool.map(function(x){ return {t:x,c:false,html:numOpt(x)}; }))),
    tip:'先数下面的 '+bottom+' 个，再数上面的 '+top+' 个，加起来是 '+(bottom+top)+' 个。' };
});
SHAPE_GENS.push(function gSymmetry(){            // 大纲 21：对称图形
  var opts=shuffle([{html:optHTML(svgSymmetry(true),'①'),c:true},
    {html:optHTML(svgSymmetry(false),'②'),c:false},
    {html:optHTML(flatSVG('para',60),'③'),c:false},
    {html:optHTML(flatSVG('rtriangle',60),'④'),c:false}]);
  return { prompt:'哪个图形沿着虚线对折后，两边能<b>完全重合</b>？', stat:'shape', options:opts,
    tip:'沿虚线对折，两边一模一样、能叠在一起的就是对称图形。' };
});
SHAPE_GENS.push(function gTangram(){             // 大纲 17：七巧板
  return { prompt:'七巧板里有什么图形？<div class="ex-shape">'+svgTangram()+'</div>', stat:'shape',
    options:shuffle([{t:'三角形',c:true},{t:'圆形',c:false},{t:'椭圆形',c:false},{t:'球体',c:false}]),
    tip:'七巧板里有三角形、正方形和平行四边形，没有圆圆的图形。' };
});

/* 随机取一个题型（与逻辑模块同款调度） */
function genShapeQ(){ return SHAPE_GENS[rnd(0,SHAPE_GENS.length-1)](); }
/* 认字题型（对应识字表：先看图猜意思，再看字，最后读拼音） */
var _eCount={}; CHARS.forEach(function(c){ _eCount[c.e]=(_eCount[c.e]||0)+1; });
var CHAR_PIC=CHARS.filter(function(c){ return _eCount[c.e]===1; });   // emoji 唯一的字，看图题才不会歧义
function genCharAudioQ(){                       // 听音选字（全部字）
  const qc=pick(CHARS);
  const others=sample(CHARS.filter(c=>c.c!==qc.c),3);
  return { prompt:'听一听，是哪个字？', stat:'char', qaudio:qc.f,
    options:shuffle([{t:qc.c,c:true},...others.map(c=>({t:c.c,c:false}))]),
    tip:'这个字读 '+qc.p+'，再听一遍找找看。' };
}
function genCharPicQ(){                          // 看图选字
  const q=pick(CHAR_PIC);
  const others=sample(CHAR_PIC.filter(c=>c.c!==q.c&&c.e!==q.e),3);
  return { prompt:'看图，是哪个字？<div class="ex-shape" style="font-size:62px;line-height:1.2">'+q.e+'</div>', stat:'char',
    options:shuffle([{t:q.c,c:true},...others.map(c=>({t:c.c,c:false}))]),
    tip:'这个图是「'+q.c+'」，读 '+q.p+'。' };
}
function genCharPicRevQ(){                       // 看字选图
  const q=pick(CHAR_PIC);
  const others=sample(CHAR_PIC.filter(c=>c.c!==q.c&&c.e!==q.e),3);
  const wrap=e=>'<div style="font-size:40px;line-height:1.2">'+e+'</div>';
  return { prompt:'「'+q.c+'」（'+q.p+'）是哪一张图？', stat:'char',
    options:shuffle([{t:q.c,c:true,html:wrap(q.e)},...others.map(c=>({t:c.c,c:false,html:wrap(c.e)}))]),
    tip:'「'+q.c+'」读 '+q.p+'，看图想一想哪个对。' };
}
var CHAR_GENS=[genCharAudioQ,genCharPicQ,genCharPicRevQ];
function genCharQ(){ return CHAR_GENS[rnd(0,CHAR_GENS.length-1)](); }

